"""Run a label-withheld task4 material hypothesis experiment (no device access).

Requires numpy/scipy/matplotlib. Example commands and boundaries are in
docs/decisions/stacked-scintillator-material-imaging.md.
"""
from __future__ import annotations

import argparse
import csv
import importlib.util
import json
import sys
from pathlib import Path

# Keep generated bytecode out of maintained tools directories.
sys.dont_write_bytecode = True

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
from scipy.ndimage import binary_erosion

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "lib"))
from material_inference import (Coefficients, basis_lookup, detector_response, forward,
                                invert_basis, match_unknown, match_basis_unknown, sha256, source_records)


def load_json(path):
    return json.loads(path.read_text(encoding="utf-8-sig"))


def verify_cache(root):
    report = load_json(root / "spectral.json")
    result = load_json(root / "result.json")
    if sha256(root / "spectral.json") != result["spectralSha256"]:
        raise ValueError("spectral report seal mismatch")
    for item in report["artifacts"]:
        path = (root / item["path"]).resolve()
        if not path.is_relative_to(root.resolve()) or sha256(path) != item["sha256"]:
            raise ValueError(f"invalid spectral artifact: {item['path']}")
    return report


def samples(root, view_step=8, pixel_step=4):
    shape = (360, 256, 256)
    g, b = [np.memmap(root / band / "projections.f32le", mode="r", dtype="<f4").reshape(shape)
            for band in ["green", "blue"]]
    gm, bm = [np.memmap(root / band / "detector-quality.bin", mode="r", dtype="u1").reshape(shape)
              for band in ["green", "blue"]]
    yy, xx = np.mgrid[:256, :256]
    support = ((xx - 127.5) ** 2 + (yy - 127.5) ** 2 < 100 ** 2)
    # Reject noise censoring/low gain; exclude edge mixing using both channels.
    valid = (gm == 1) & (bm == 1) & (g > .4) & (b > .3) & (g < 4) & (b < 4) & support
    eroded = binary_erosion(valid, structure=np.ones((1, 5, 5)), border_value=0)
    positions = np.array(np.where(eroded[::view_step, ::pixel_step, ::pixel_step])).T
    positions *= [view_step, pixel_step, pixel_step]
    idx = tuple(positions.T)
    observed = np.column_stack([g[idx], b[idx]]).astype(float)
    if len(observed) < 500:
        raise ValueError("insufficient jointly measured interior rays")
    return observed, positions, {"allJointMeasuredInteriorRays": int(eroded.sum()),
                                  "sampledRays": len(observed), "shape": list(shape),
                                  "sampling": [view_step, pixel_step, pixel_step]}


def uncertainties(root, positions, observed):
    # Dark + reference noise in logarithmic coordinates. Does not invent photon counts.
    out = []
    rows, cols = positions[:, 1], positions[:, 2]
    for k, band in enumerate(["green", "blue"]):
        def read(name):
            return np.fromfile(root / band / name, dtype="<f4").reshape(256, 256)[rows, cols]
        gain = read("flat-crop.f32le") - read("dark-crop.f32le")
        dark_var = read("dark-variance.f32le")
        flat_var = read("flat-variance.f32le")
        signal = gain * np.exp(-observed[:, k])
        variance = dark_var * 1.1 / signal ** 2 + (flat_var + dark_var) / (10 * gain ** 2)
        out.append(np.sqrt(np.maximum(variance, 0)))
    # Global robust diagonal scale; spatial noise values are also saved for inspection.
    return np.maximum(np.median(np.array(out), axis=1), .005), np.array(out).T


def summary(candidates, scores, paths, ids):
    s = np.median(scores[ids], axis=0)
    order = np.argsort(s, kind="stable")
    best = scores[ids].min(axis=1)
    rows = []
    for rank, i in enumerate(order):
        c = candidates[i]
        rows.append({"rank": rank + 1, "candidate": c["name"], "category": c["category"],
                     "medianSquaredNoiseResidual": float(s[i]),
                     "withinOneNoiseUnitOfRayBestFraction": float(np.mean(scores[ids, i] <= best + 1)),
                     "medianEquivalentPathMm": float(np.median(paths[ids, i]) / c["density_g_cm3"] * 10),
                     "pathP10P90Mm": (np.percentile(paths[ids, i], [10, 90]) / c["density_g_cm3"] * 10).tolist()})
    return rows


def write_csv(path, rows):
    with path.open("w", newline="", encoding="utf-8-sig") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--method", required=True, type=Path)
    parser.add_argument("--cache", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--coeff-dir", type=Path)
    args = parser.parse_args()
    out = args.output.resolve()
    if out.exists() and any(out.iterdir()):
        raise ValueError("use a fresh output directory to preserve earlier evidence")
    out.mkdir(parents=True, exist_ok=True)
    method, root = args.method.resolve(), args.cache.resolve()
    spectral = verify_cache(root)
    data = method / "help_datas"
    coefficient_dir = args.coeff_dir
    if coefficient_dir is None:
        module = importlib.util.find_spec("xrayatten")
        if module is None:
            raise ValueError("specify --coeff-dir or use the existing xrayatten environment")
        coefficient_dir = Path(module.origin).parent / "data" / "nist_local" / "coeff"
    coefficient_dir = coefficient_dir.resolve()
    coeff = Coefficients(coefficient_dir, data / "elements.csv")
    candidates = load_json(data / "common_materials_db.json")
    if len({c["name"] for c in candidates}) != len(candidates):
        raise ValueError("duplicate material names")
    with (data / "Energy_spec_smoothed.csv").open(encoding="utf-8-sig") as handle:
        rows = list(csv.reader(handle))[1:]
    full_energy = np.array([float(row[0]) for row in rows])
    full_counts = np.maximum(np.array([float(row[-1]) for row in rows]), 0)
    observed, positions, selection = samples(root)
    sigma, individual_sigma = uncertainties(root, positions, observed)
    # Explicit nuisance grid fixed before ranking. No object shape/material priors.
    scenarios = [
        {"name": "reference60", "maximumKeV": 59.899520874, "densityScale": 1., "mixing": 0., "extraAlMm": 0.},
        {"name": "reference50", "maximumKeV": 50., "densityScale": 1., "mixing": 0., "extraAlMm": 0.},
        {"name": "density0.7", "maximumKeV": 59.899520874, "densityScale": .7, "mixing": 0., "extraAlMm": 0.},
        {"name": "density1.3", "maximumKeV": 59.899520874, "densityScale": 1.3, "mixing": 0., "extraAlMm": 0.},
        {"name": "mix0.15", "maximumKeV": 59.899520874, "densityScale": 1., "mixing": .15, "extraAlMm": 0.},
        {"name": "mix0.30", "maximumKeV": 59.899520874, "densityScale": 1., "mixing": .30, "extraAlMm": 0.},
        {"name": "filter0.5", "maximumKeV": 59.899520874, "densityScale": 1., "mixing": 0., "extraAlMm": .5},
        {"name": "filter1.0", "maximumKeV": 59.899520874, "densityScale": 1., "mixing": 0., "extraAlMm": 1.},
    ]
    all_ids = np.ones(len(observed), dtype=bool)
    # Geometric angle split fixed before fitting: each ray fits its own unknown path.
    fit_ids = positions[:, 0] % 3 != 2
    held_ids = ~fit_ids
    ratio = observed[:, 1] / observed[:, 0]
    strong_ids = observed[:, 0] > 1.
    scenario_reports, scores_all = [], []
    basis_reports = []
    for number, scenario in enumerate(scenarios):
        mask = (full_energy >= 1) & (full_energy <= scenario["maximumKeV"])
        energy, counts = full_energy[mask], full_counts[mask]
        weights = detector_response(data, energy, counts, scenario["densityScale"],
                                    scenario["mixing"], scenario["extraAlMm"], coeff)
        curves = {c["name"]: coeff.compound(c["composition"], energy) for c in candidates}
        basis_mu = np.array([coeff.element(name, energy) for name in ["Al", "Cu"]])
        coordinates, response = basis_lookup(basis_mu, weights)
        estimates, distance = invert_basis(observed, coordinates, response, sigma)
        scores, paths = match_unknown(observed, candidates, curves, weights, sigma)
        basis_rankings, basis_match_diagnostics = match_basis_unknown(
            estimates, distance, candidates, curves, weights, coordinates, response, sigma, basis_mu)
        rankings = summary(candidates, scores, paths, all_ids)
        fit_rankings = summary(candidates, scores, paths, fit_ids)
        held_rankings = summary(candidates, scores, paths, held_ids)
        strong_rankings = summary(candidates, scores, paths, strong_ids)
        thin_jacobian = weights @ basis_mu.T
        basis_report = {"scenario": scenario["name"], "basisNames": ["Al", "Cu"],
                        "units": "equivalent basis areal density g/cm2",
                        "thinJacobian": thin_jacobian.tolist(),
                        "thinJacobianCondition": float(np.linalg.cond(thin_jacobian)),
                        "lookupRangesGcm2": [5, 3], "lookupPointsPerAxis": 100,
                        "withinOneNoiseUnitFraction": float(np.mean(distance <= 1)),
                        "boundaryFraction": float(np.mean(np.any(estimates == 0, axis=1))),
                        "medianBasisArealDensity": np.median(estimates, axis=0).tolist()}
        basis_reports.append(basis_report)
        report = {**scenario, "responseMeanKeV": (weights @ energy).tolist(),
                  "basisMatching": basis_match_diagnostics, "basisMatchingTop10": basis_rankings[:10],
                  "overallTop10": rankings[:10], "fitAngleTop5": fit_rankings[:5],
                  "heldAngleTop5": held_rankings[:5], "strongAttenuationTop10": strong_rankings[:10]}
        scenario_reports.append(report)
        scores_all.append(np.median(scores[strong_ids], axis=0))
        write_csv(out / f"{scenario['name']}-rankings.csv", rankings)
        write_csv(out / f"{scenario['name']}-basis-match-rankings.csv", basis_rankings)
        # Candidate curves in the SAME two-basis coordinates, with nonlinear beam hardening.
        library_basis = []
        for c in candidates:
            tau = np.geomspace(1e-4, c["density_g_cm3"] * 4, 20)
            p = forward(curves[c["name"]], tau, weights)
            xy, residual = invert_basis(p, coordinates, response, sigma)
            for t, point, error in zip(tau, xy, residual):
                library_basis.append({"candidate": c["name"], "pathMm": float(t / c["density_g_cm3"] * 10),
                                      "basisAlGcm2": float(point[0]), "basisCuGcm2": float(point[1]),
                                      "basisNoiseResidual": float(error)})
        write_csv(out / f"{scenario['name']}-library-basis.csv", library_basis)
        if number == 0:
            np.savez_compressed(out / "sampled-ray-fits.npz", positions=positions, observed=observed,
                                sigma=individual_sigma, basis=estimates, basis_noise_residual=distance,
                                candidate_scores=scores, candidate_tau_gcm2=paths,
                                candidate_names=np.array([c["name"] for c in candidates]))
            best = np.argmin(scores, axis=1)
            sorted_scores = np.sort(scores, axis=1)
            ambiguous = sorted_scores[:, 1] - sorted_scores[:, 0] < 1
            best_rows = [{"view": int(pos[0]), "row": int(pos[1]), "column": int(pos[2]),
                          "pGreen": float(p[0]), "pBlue": float(p[1]), "bestHypothesis": candidates[i]["name"],
                          "equivalentPathMm": float(paths[k, i] / candidates[i]["density_g_cm3"] * 10),
                          "ambiguous": bool(ambiguous[k]), "basisAlGcm2": float(estimates[k, 0]),
                          "basisCuGcm2": float(estimates[k, 1]), "basisNoiseResidual": float(distance[k])}
                         for k, (pos, p, i) in enumerate(zip(positions, observed, best))]
            write_csv(out / "sampled-ray-hypotheses.csv", best_rows)
            base_diagnostics = {"singleMaterialFitWithinOneNoiseUnitFraction": float(np.mean(scores.min(axis=1) <= 1)),
                                "ambiguousFirstSecondFraction": float(ambiguous.mean()),
                                "blueToGreenLogRatioP10P50P90": np.percentile(ratio, [10, 50, 90]).tolist(),
                                "ratioAboveOneFraction": float(np.mean(ratio > 1))}
            # Spectral scatter contains no shape image or target name.
            fig, axs = plt.subplots(1, 3, figsize=(15, 4.8), layout="constrained")
            axs[0].hexbin(observed[:, 0], observed[:, 1], gridsize=65, bins="log", mincnt=1, cmap="Greys")
            colors = plt.get_cmap("tab10")
            for i, c in enumerate(strong_rankings[:6]):
                candidate = next(x for x in candidates if x["name"] == c["candidate"])
                tau = np.geomspace(1e-5, candidate["density_g_cm3"] * 4, 200)
                trajectory = forward(curves[c["candidate"]], tau, weights)
                axs[0].plot(*trajectory.T, label=c["candidate"], color=colors(i))
            axs[0].set(xlim=(0, 4), ylim=(0, 4), xlabel="Green log attenuation", ylabel="Blue log attenuation",
                       title="Unknown paths vs library trajectories")
            axs[0].legend(fontsize=7)
            axs[1].hexbin(estimates[:, 0], estimates[:, 1], gridsize=60, bins="log", mincnt=1, cmap="viridis")
            axs[1].set(xlabel="Equivalent Al (g/cm²)", ylabel="Equivalent Cu (g/cm²)", title="Nonnegative Al-Cu basis hypothesis")
            bars = strong_rankings[:10]
            axs[2].barh([x["candidate"] for x in bars][::-1],
                        [x["medianSquaredNoiseResidual"] for x in bars][::-1], color="#336b9b")
            axs[2].set(xlabel="Median squared noise-scaled residual", title="Unknown material + unknown thickness")
            fig.suptitle("Task4 — uncalibrated response hypothesis; labels and object shape withheld", fontsize=12)
            fig.savefig(out / "spectral-hypotheses.png", dpi=180)
            plt.close(fig)
        print(json.dumps({"scenario": scenario["name"], "strongTop3": [x["candidate"] for x in strong_rankings[:3]],
                          "basisWithinNoise": basis_report["withinOneNoiseUnitFraction"]}), flush=True)
    rank_indices = np.argsort(np.array(scores_all), axis=1)
    top1 = [candidates[i]["name"] for i in rank_indices[:, 0]]
    sensitivity = [{"candidate": c["name"], "top1Scenarios": int(np.sum(rank_indices[:, 0] == i)),
                    "top5Scenarios": int(np.sum(np.any(rank_indices[:, :5] == i, axis=1)))}
                   for i, c in enumerate(candidates)]
    sensitivity.sort(key=lambda x: (-x["top1Scenarios"], -x["top5Scenarios"], x["candidate"]))
    sources = set(coeff.sources) | {data / "common_materials_db.json", data / "Energy_spec_smoothed.csv",
                                    method / "outputs/10_v7_test2_four_bin_open_interp/scripts/run_v7_test2_four_bin_open_interp.py",
                                    method / "Method-材料属性-v7.md", Path(__file__).resolve(),
                                    Path(__file__).resolve().parents[1] / "lib/material_inference.py"}
    sources |= set((data / "mulit_layer_encoder").glob("*/*local.txt"))
    report = {"schemaVersion": 1, "experiment": "unknown material and unknown path thickness",
              "measurement": "hypothesis", "quantitativeMaterialIdentification": False,
              "targetLabelsUsed": False, "targetThicknessUsed": False, "shapePriorUsed": False,
              "detectorStack": spectral["options"]["layers"], "candidateCount": len(candidates),
              "candidateLibraryPolicy": "all entries in supplied Method database, no target-dependent filtering",
              "basisPolicy": "fixed Al-Cu pair from supplied Method script, no target-dependent selection",
              "thicknessBoundMm": [0, 40], "noiseSigma": sigma.tolist(), "selection": selection,
              "fitAndHeldAngles": [int(fit_ids.sum()), int(held_ids.sum())],
              "baseDiagnostics": base_diagnostics, "basisDiagnostics": basis_reports,
              "scenarios": scenario_reports, "strongAttenuationSensitivity": sensitivity,
              "stableStrongTop1AcrossScenarios": len(set(top1)) == 1,
              "limits": ["Method glass compositions/densities are detector hypotheses, not task4 measurements",
                         "Method source spectrum truncated to working kV is not a measured task4 source spectrum",
                         "uncalibrated optical mixing, layer depth, scattering and beam hardening remain",
                         "ray candidates assume a single homogeneous material; overlaps need basis CT and voxel matching",
                         "nearby candidates and low-Z materials can be indistinguishable; no forced class output",
                         "object description was disclosed before execution but is absent from fitting inputs/code",
                         "basis coefficients describe equivalent paths, not actual Al or Cu content"],
              "inputCache": str(root), "inputSpectralSha256": sha256(root / "spectral.json"),
              "sources": source_records(sources)}
    (out / "report.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    write_csv(out / "sensitivity.csv", sensitivity)
    # Ensure our read-only input artifacts still match their original seal.
    verify_cache(root)
    print(json.dumps({"output": str(out), "candidateCount": len(candidates), "selection": selection,
                      "baseDiagnostics": base_diagnostics, "sensitivityTop": sensitivity[:10]}, ensure_ascii=False), flush=True)


if __name__ == "__main__":
    main()
